import { Union } from "./fable_modules/fable-library-js.5.21.0/Types.js";
import { union_type, string_type } from "./fable_modules/fable-library-js.5.21.0/Reflection.js";
import { join } from "./fable_modules/fable-library-js.5.21.0/String.js";
import { empty, singleton, append, delay, toArray } from "./fable_modules/fable-library-js.5.21.0/Seq.js";
import { AnnotatedHelper, OpaqueHelper } from "./Helpers.fs.jsx";
import { untrack } from "solid-js";

export class Kind extends Union {
    constructor(tag, fields) {
        super();
        this.tag = tag;
        this.fields = fields;
    }
    cases() {
        return ["Alpha", "Beta", "Other"];
    }
    static Alpha = new Kind(0, []);
    static Other = new Kind(2, []);
}

export function Kind_$reflection() {
    return union_type("AstTriage.Kind", [], Kind, () => [[], [["Item", string_type]], []]);
}

export function BranchChildren(flag) {
    return <div>
        {flag ? ((<span>
            one
        </span>, <b>
            two
        </b>)) : ("empty")}
    </div>;
}

export function BranchExplicitChildren(flag) {
    return <div>
        {flag ? ((<span>
            one
        </span>, <b>
            two
        </b>)) : ("empty")}
    </div>;
}

export function BranchDiscardElement(flag) {
    return <div>
        {flag ? ((<span>
            one
        </span>, <b>
            two
        </b>)) : ("empty")}
    </div>;
}

export function BranchEffect(flag, log) {
    return <div>
        {flag ? ((log("one"), <b>
            two
        </b>)) : ("empty")}
    </div>;
}

export function BranchTexts(flag) {
    return <div>
        {flag ? ("two") : ("empty")}
    </div>;
}

export function BranchDiscardText(flag) {
    return <div>
        {flag ? ("two") : ("empty")}
    </div>;
}

export function BranchBoundChildren(flag, text) {
    let upper;
    return <div>
        {flag ? ((upper = text.toLocaleUpperCase(), (<span>
            {upper}
        </span>, <b>
            {text}
        </b>))) : ("empty")}
    </div>;
}

export function UnionPayload(kind) {
    return <div>
        {(kind.tag === 1) ? (<span>
            {kind}
        </span>) : ("empty")}
    </div>;
}

export function UnionLength(kind) {
    return <div>
        {(kind.tag === 1) ? (<span>
            {kind.length}
        </span>) : ("empty")}
    </div>;
}

export function OmittedArrayItem(flag) {
    return <div title={join(":", ["head", flag ? "yes" : null, "tail"])}>
        body
    </div>;
}

export function OmittedArrayItemSkip(flag) {
    return <div title={join(":", toArray(delay(() => append(singleton("head"), delay(() => append(flag ? singleton("yes") : empty(), delay(() => singleton("tail"))))))))}>
        body
    </div>;
}

export function IdentityCallback() {
    return <button onClick={(value) => {
        }}>
        body
    </button>;
}

export function DiscardedCall(produce) {
    return <div>
        {produce()}
        tail
    </div>;
}

export function YieldedCall(produce) {
    return <div>
        {produce()}
        tail
    </div>;
}

export function FragmentBranch(flag) {
    return <div>
        {flag ? (<>
            <span>
                one
            </span>
            <b>
                two
            </b>
        </>) : ("empty")}
    </div>;
}

export function LocalOutsideCe(text) {
    const upper = text.toLocaleUpperCase();
    return <div>
        <span>
            {upper}
        </span>
        <b>
            {text}
        </b>
    </div>;
}

export function CallsOpaqueHelper() {
    return <div>
        {OpaqueHelper()}
    </div>;
}

export function CallsAnnotatedHelper() {
    return <div>
        {untrack(AnnotatedHelper)}
    </div>;
}

